using System;using System.Collections.Generic;using System.IO;
class Log{internal static void Warning(string value){}}
class Program{
static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}static void Main(){
var strings=new Dictionary<string,string>{{"xuiRebirthPurgeObjectiveTarget","Target {0}%"},{"xuiRebirthPurgeObjectiveBiome","{0}: {1}/{2} cleared; {3} remaining; {4}/{5} discovered"},{"xuiRebirthPurgeObjectiveNotApplicable","{0}: not applicable"},{"xuiRebirthPurgeObjectiveRules","Rules"},{"biome_pine_forest","Pine Forest"},{"biome_desert","Desert"}};Func<string,string> localize=key=>strings.TryGetValue(key,out var value)?value:key;
var forest=new RebirthPurgeObjectiveFrame.Biome("forest",4,3,2,new Dictionary<int,int>{{1,4}},new Dictionary<int,int>{{1,2}});var absent=new RebirthPurgeObjectiveFrame.Biome("desert",0,0,0,new Dictionary<int,int>(),new Dictionary<int,int>());
string text=RebirthPurgeObjectiveText.Format(new[]{forest,absent},75,localize);Check(text.Contains("Target 75%"),"configured target appears");Check(text.Contains("Pine Forest: 2/3 cleared; 1 remaining; 3/4 discovered"),"correct rounded target and concrete remaining count");Check(text.Contains("Desert: not applicable"),"zero eligible biome is not blocked or completed");Check(text.IndexOf("Desert")<text.IndexOf("Pine Forest"),"stable biome order independent of dictionary ordering");Check(text.EndsWith("Rules"),"eligibility and reset explanation included");
var complete=new RebirthPurgeObjectiveFrame.Biome("forest",4,4,4,new Dictionary<int,int>{{1,4}},new Dictionary<int,int>{{1,4}});Check(RebirthPurgeObjectiveText.Format(new[]{complete},75,localize).Contains("0 remaining"),"over-target completion never displays negative remaining");var custom=new RebirthPurgeObjectiveFrame.Biome("custom_biome",1,1,1,new Dictionary<int,int>{{1,1}},new Dictionary<int,int>{{1,1}});Check(RebirthPurgeObjectiveText.Format(new[]{custom},100,localize).Contains("custom biome:"),"custom biome fallback does not expose untranslated key");Check(RebirthPurgeObjectiveText.Format(new RebirthPurgeObjectiveFrame.Biome[0],75,localize)=="Target 75%\nRules","world without eligible combat POIs has no fabricated totals");
Console.WriteLine("RESULT "+checks+" PASS; production formatting/policy/frame; native XUi rendering not exercised.");}}